"""Run QnA predictions over markdown generated by an external PDF parser."""
from __future__ import annotations

import argparse
import fnmatch
import json
import logging
import sys
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass
from pathlib import Path
from typing import Any

# Scenario 3 intentionally reuses the proven model configuration and API clients
# from scenario 1.  This keeps all 12 model definitions and endpoint quirks in one
# place while this package owns parser-output discovery and result persistence.
_REPO_ROOT = Path(__file__).resolve().parents[3]
_PDF_QNA_SRC = _REPO_ROOT / "pdf_qna" / "src"
if str(_PDF_QNA_SRC) not in sys.path:
    sys.path.insert(0, str(_PDF_QNA_SRC))

from pdfqna.config import EvalConfig, ModelSpec, load_config  # pyright: ignore[reportMissingImports]  # noqa: E402
from pdfqna.qa_runner import build_clients, run_qa  # pyright: ignore[reportMissingImports]  # noqa: E402

logger = logging.getLogger(__name__)

_DEFAULT_ENV = Path("experiment.env")
_DEFAULT_DATASET = Path("dataset")
_DEFAULT_PARSER_ROOT = _REPO_ROOT / "pdf_parsers" / "docling" / "output"
_DEFAULT_OUTPUT = _REPO_ROOT / "pdf_qna_with_parser" / "results" / "docling"


@dataclass(frozen=True)
class ParserDocument:
    config: str
    doc_id: str
    markdown_path: Path
    quest_path: Path


def _index_parser_markdown(parser_root: Path) -> dict[str, Path]:
    """Index parser markdown recursively by document ID, rejecting ambiguity."""
    if not parser_root.is_dir():
        raise FileNotFoundError(f"Parser output directory not found: {parser_root}")

    candidates: dict[str, list[Path]] = defaultdict(list)
    for path in sorted(parser_root.rglob("*.md")):
        candidates[path.stem].append(path)

    index: dict[str, Path] = {}
    for doc_id, paths in candidates.items():
        canonical = [path for path in paths if path.parent.name == doc_id]
        usable = canonical or paths
        if len(usable) > 1:
            formatted = "\n  ".join(str(path) for path in usable)
            raise ValueError(f"Multiple parser markdown files found for {doc_id}:\n  {formatted}")
        index[doc_id] = usable[0]
    return index


def discover_docs(
    dataset_dir: Path,
    parser_root: Path,
    config_filter: str | None = None,
    max_docs: int | None = None,
) -> list[ParserDocument]:
    """Match dataset question files to parser-produced markdown by document ID."""
    if not dataset_dir.is_dir():
        raise FileNotFoundError(f"Dataset directory not found: {dataset_dir}")

    markdown_by_doc = _index_parser_markdown(parser_root)
    docs: list[ParserDocument] = []
    missing: list[str] = []

    config_dirs = sorted(path for path in dataset_dir.iterdir() if path.is_dir())
    if config_filter:
        config_dirs = [
            path for path in config_dirs if fnmatch.fnmatch(path.name, config_filter)
        ]

    for config_dir in config_dirs:
        quest_dir = config_dir / "quest"
        if not quest_dir.is_dir():
            continue
        for quest_path in sorted(quest_dir.glob("*.json")):
            doc_id = quest_path.stem
            markdown_path = markdown_by_doc.get(doc_id)
            if markdown_path is None:
                missing.append(f"{config_dir.name}/{doc_id}")
                continue
            docs.append(
                ParserDocument(config_dir.name, doc_id, markdown_path, quest_path)
            )
            if max_docs and len(docs) >= max_docs:
                return docs

    if missing:
        logger.warning(
            "Skipped %d dataset document(s) without parser markdown; first: %s",
            len(missing),
            ", ".join(missing[:5]),
        )
    return docs


def load_questions(path: Path) -> list[dict[str, Any]]:
    raw = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(raw, list):
        raw = [raw]
    return raw


def _question_metadata(question: dict[str, Any], index: int) -> dict[str, Any]:
    refs = question.get("refs") or [{}]
    assertions = question.get("assertions") or []
    return {
        "question_id": question.get("Id", f"Q{index + 1}"),
        "question": question.get("query", ""),
        "element_type": refs[0].get("element_type", "unknown"),
        "assertion": assertions[0].get("text", "") if assertions else "",
    }


def _call_model(
    clients: dict[str, Any],
    spec: ModelSpec,
    markdown: str,
    question: str,
    label: str,
) -> tuple[str, dict[str, Any]]:
    return spec.name, run_qa(clients, spec, markdown, question, label)


def _run_question(
    metadata: dict[str, Any],
    markdown: str,
    cfg: EvalConfig,
    clients: dict[str, Any],
    existing: dict[str, Any] | None = None,
) -> dict[str, Any]:
    existing = existing or {}
    to_run = [
        spec
        for spec in cfg.models
        if spec.name not in existing
        or existing[spec.name].get("status") == "skip"
        or existing[spec.name].get("error")
        or not existing[spec.name].get("predicted")
    ]
    fresh: dict[str, Any] = {}
    if to_run:
        with ThreadPoolExecutor(max_workers=cfg.workers) as pool:
            futures = {
                pool.submit(
                    _call_model,
                    clients,
                    spec,
                    markdown,
                    metadata["question"],
                    f"{metadata['question_id']}|{spec.name}",
                ): spec.name
                for spec in to_run
            }
            for future in as_completed(futures):
                model_name, result = future.result()
                fresh[model_name] = result

    model_results = {
        spec.name: fresh.get(spec.name, existing.get(spec.name, {}))
        for spec in cfg.models
        if spec.name in fresh or spec.name in existing
    }
    return {**metadata, "model_results": model_results}


def _load_cached(path: Path) -> dict[str, dict[str, Any]]:
    cached: dict[str, dict[str, Any]] = {}
    if not path.exists():
        return cached
    for line_number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if not raw.strip():
            continue
        try:
            entry = json.loads(raw)
        except json.JSONDecodeError as exc:
            logger.warning("Ignoring malformed %s:%d: %s", path.name, line_number, exc)
            continue
        question_id = entry.get("question_id")
        if question_id:
            cached[question_id] = entry
    return cached


def _is_complete(entry: dict[str, Any], model_names: set[str]) -> bool:
    results = entry.get("model_results", {})
    return all(
        name in results
        and results[name].get("status") != "skip"
        and not results[name].get("error")
        and bool(results[name].get("predicted"))
        for name in model_names
    )


def infer_doc(
    doc: ParserDocument,
    parser_name: str,
    cfg: EvalConfig,
    clients: dict[str, Any],
    per_doc_dir: Path,
    max_qa: int | None = None,
) -> list[dict[str, Any]]:
    """Predict every selected question and checkpoint one JSONL line per question."""
    output_path = per_doc_dir / f"{doc.config}__{doc.doc_id}.jsonl"
    cached = _load_cached(output_path) if cfg.resume else {}
    questions = load_questions(doc.quest_path)
    if cfg.important_queries:
        questions = [q for q in questions if q.get("query", "") in cfg.important_queries]
    if max_qa:
        questions = questions[:max_qa]

    metadata = [_question_metadata(question, i) for i, question in enumerate(questions)]
    model_names = {spec.name for spec in cfg.models}
    if all(
        item["question_id"] in cached
        and _is_complete(cached[item["question_id"]], model_names)
        for item in metadata
    ):
        logger.info("  all %d question(s) cached", len(metadata))
        return [cached[item["question_id"]] for item in metadata]

    markdown = doc.markdown_path.read_text(encoding="utf-8", errors="replace")
    if not markdown.strip():
        raise ValueError(f"Parser markdown is empty: {doc.markdown_path}")

    mode = "a" if cfg.resume else "w"
    results: list[dict[str, Any]] = []
    with output_path.open(mode, encoding="utf-8") as stream:
        for index, item in enumerate(metadata, 1):
            old = cached.get(item["question_id"])
            if old and _is_complete(old, model_names):
                logger.info("  Q%d/%d %s (cached)", index, len(metadata), item["question_id"])
                results.append(old)
                continue

            logger.info("  Q%d/%d %s", index, len(metadata), item["question_id"])
            result = _run_question(
                item,
                markdown,
                cfg,
                clients,
                existing=old.get("model_results", {}) if old else None,
            )
            entry = {
                "config": doc.config,
                "doc_id": doc.doc_id,
                "md_path": str(doc.markdown_path),
                "markdown_source": parser_name,
                "parser_name": parser_name,
                **result,
            }
            stream.write(json.dumps(entry, ensure_ascii=False) + "\n")
            stream.flush()
            results.append(entry)
    return results


def write_prediction_summary(per_doc_dir: Path, output_dir: Path) -> None:
    """Aggregate the latest question records into model-level prediction stats."""
    latest: dict[tuple[str, str, str], dict[str, Any]] = {}
    for path in sorted(per_doc_dir.glob("*.jsonl")):
        for raw in path.read_text(encoding="utf-8").splitlines():
            if not raw.strip():
                continue
            try:
                entry = json.loads(raw)
            except json.JSONDecodeError:
                continue
            key = (entry.get("config", ""), entry.get("doc_id", ""), entry.get("question_id", ""))
            latest[key] = entry

    counters: dict[str, dict[str, Any]] = defaultdict(
        lambda: {
            "total": 0,
            "success": 0,
            "error": 0,
            "skip": 0,
            "refusal": 0,
            "response_time_seconds": 0.0,
            "prompt_tokens": 0,
            "completion_tokens": 0,
        }
    )
    for entry in latest.values():
        for model, result in entry.get("model_results", {}).items():
            stats = counters[model]
            stats["total"] += 1
            if result.get("status") == "skip":
                stats["skip"] += 1
            elif result.get("error"):
                stats["error"] += 1
            elif result.get("predicted"):
                stats["success"] += 1
            else:
                stats["error"] += 1
            stats["refusal"] += int(bool(result.get("model_refuse")))
            stats["response_time_seconds"] += float(result.get("response_time", 0.0))
            stats["prompt_tokens"] += int(result.get("prompt_tokens", 0))
            stats["completion_tokens"] += int(result.get("completion_tokens", 0))

    summary = {
        "documents": len({(key[0], key[1]) for key in latest}),
        "questions": len(latest),
        "by_model": {},
    }
    for model, stats in sorted(counters.items()):
        stats["success_rate"] = round(stats["success"] / stats["total"], 4) if stats["total"] else 0.0
        stats["response_time_seconds"] = round(stats["response_time_seconds"], 3)
        summary["by_model"][model] = stats
    output_dir.mkdir(parents=True, exist_ok=True)
    (output_dir / "prediction_summary.json").write_text(
        json.dumps(summary, ensure_ascii=False, indent=2), encoding="utf-8"
    )


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(
        description="Run 12-model QnA prediction over PDF-parser markdown outputs."
    )
    parser.add_argument("--env", default=str(_DEFAULT_ENV), metavar="PATH")
    parser.add_argument("--dataset-dir", default=str(_DEFAULT_DATASET), metavar="PATH")
    parser.add_argument("--parser-root", default=str(_DEFAULT_PARSER_ROOT), metavar="PATH")
    parser.add_argument("--parser-name", default="docling", metavar="NAME")
    parser.add_argument("--output-dir", default=str(_DEFAULT_OUTPUT), metavar="PATH")
    parser.add_argument("--config-filter", metavar="PATTERN")
    parser.add_argument("--important-queries", metavar="PATH")
    parser.add_argument("--max-docs", type=int, metavar="N")
    parser.add_argument("--max-qa", type=int, metavar="N")
    parser.add_argument("--max-total-qa", type=int, metavar="N")
    parser.add_argument("--workers", type=int, default=5, metavar="N")
    parser.add_argument(
        "--exclude-models",
        metavar="NAMES",
        help="Comma-separated QA model names to exclude from this run",
    )
    parser.add_argument("--no-resume", action="store_true")
    args = parser.parse_args(argv)

    cfg = load_config(args.env)
    excluded_models = {
        name.strip() for name in (args.exclude_models or "").split(",") if name.strip()
    }
    configured_models = {model.name for model in cfg.models}
    unknown_models = excluded_models - configured_models
    if unknown_models:
        parser.error(
            "--exclude-models contains unconfigured model(s): "
            + ", ".join(sorted(unknown_models))
        )
    cfg.models = [model for model in cfg.models if model.name not in excluded_models]
    if not cfg.models:
        parser.error("--exclude-models removed every configured QA model")
    cfg.dataset_base_dir = Path(args.dataset_dir)
    cfg.output_dir = Path(args.output_dir)
    cfg.workers = args.workers
    cfg.resume = not args.no_resume
    if args.important_queries:
        raw = json.loads(Path(args.important_queries).read_text(encoding="utf-8"))
        cfg.important_queries = {item["query"] for item in raw if item.get("query")}

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)-8s %(message)s",
        datefmt="%H:%M:%S",
    )
    for noisy in ("openai", "httpx", "httpcore", "azure", "urllib3"):
        logging.getLogger(noisy).setLevel(logging.WARNING)

    docs = discover_docs(
        cfg.dataset_base_dir,
        Path(args.parser_root),
        config_filter=args.config_filter,
        max_docs=args.max_docs,
    )
    if not docs:
        logger.warning("No matching documents found")
        return

    logger.info("Models (%d): %s", len(cfg.models), ", ".join(m.name for m in cfg.models))
    logger.info("Found %d document(s); judges are intentionally not run", len(docs))
    clients = build_clients(cfg)
    per_doc_dir = cfg.output_dir / "per_doc"
    per_doc_dir.mkdir(parents=True, exist_ok=True)

    total = 0
    for index, doc in enumerate(docs, 1):
        if args.max_total_qa and total >= args.max_total_qa:
            break
        allowed = args.max_qa
        if args.max_total_qa:
            remaining = args.max_total_qa - total
            allowed = min(allowed, remaining) if allowed else remaining
        logger.info("[%d/%d] %s / %s", index, len(docs), doc.config, doc.doc_id)
        results = infer_doc(doc, args.parser_name, cfg, clients, per_doc_dir, allowed)
        total += len(results)

    write_prediction_summary(per_doc_dir, cfg.output_dir)
    logger.info("Done. Results: %s", cfg.output_dir)


if __name__ == "__main__":
    main()